import type { Metadata } from "next";

export const metadata: Metadata = {
  title: "Reservei · Admin",
  description: "Painel administrativo do Complexo Esportivo.",
};

export default function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return <>{children}</>;
}

"use client";

import { AdminShell } from "@/components/admin/AdminShell";

export default function AdminIndexPage() {
  return <AdminShell />;
}

"use client";

import { AdminShell } from "@/components/admin/AdminShell";

export default function AdminDashboardPage() {
  return <AdminShell initialView="dashboard" />;
}

/**
 * Hook de autenticação mockada para o painel administrativo.
 * Usa LocalStorage como mecanismo de sessão front-end.
 *
 * BACKLOG: Substituir por autenticação real (JWT/OAuth) quando
 * houver backend. Ver BACKLOG.md.
 */

"use client";

import { useState, useEffect, useCallback } from "react";

const STORAGE_KEY = "reservei_admin_auth";
const SENHA_ADMIN = "admin123";

export function useAdminAuth() {
  const [autenticado, setAutenticado] = useState<boolean | null>(null); // null = carregando

  // Lê o estado do LocalStorage na montagem (client-only)
  useEffect(() => {
    try {
      const flag = localStorage.getItem(STORAGE_KEY);
      setAutenticado(flag === "true");
    } catch {
      setAutenticado(false);
    }
  }, []);

  const login = useCallback((senha: string): boolean => {
    if (senha === SENHA_ADMIN) {
      localStorage.setItem(STORAGE_KEY, "true");
      setAutenticado(true);
      return true;
    }
    return false;
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem(STORAGE_KEY);
    setAutenticado(false);
  }, []);

  return { autenticado, login, logout };
}

/**
 * Tela de login do painel administrativo.
 * Verifica a senha mockada e grava flag no LocalStorage.
 */

"use client";

import { useState } from "react";
import { Eye, EyeOff, Lock, Shield } from "lucide-react";

interface Props {
  onLogin: (senha: string) => boolean;
}

export function AdminLogin({ onLogin }: Props) {
  const [senha, setSenha] = useState("");
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const [erro, setErro] = useState(false);
  const [carregando, setCarregando] = useState(false);
  const [shake, setShake] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setCarregando(true);
    setErro(false);

    // Pequeno delay para dar sensação de verificação
    await new Promise((r) => setTimeout(r, 600));

    const ok = onLogin(senha);
    setCarregando(false);

    if (!ok) {
      setErro(true);
      setSenha("");
      setShake(true);
      setTimeout(() => setShake(false), 500);
    }
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
      {/* Background grid decorativo */}
      <div
        className="fixed inset-0 pointer-events-none opacity-[0.03]"
        style={{
          backgroundImage:
            "linear-gradient(var(--border) 1px, transparent 1px), linear-gradient(90deg, var(--border) 1px, transparent 1px)",
          backgroundSize: "48px 48px",
        }}
      />

      {/* Glow central */}
      <div className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] rounded-full bg-emerald-500/5 blur-3xl pointer-events-none" />

      <div
        className={`relative w-full max-w-sm transition-all duration-300 ${shake ? "animate-shake" : ""}`}
      >
        {/* Card */}
        <div className="bg-slate-900 border border-slate-700/60 rounded-2xl shadow-2xl shadow-black/50 overflow-hidden">
          {/* Header */}
          <div className="bg-gradient-to-br from-slate-800 to-slate-900 px-8 pt-10 pb-8 text-center border-b border-slate-700/40">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 mb-5">
              <Shield className="w-8 h-8 text-emerald-400" />
            </div>
            <h1 className="text-2xl font-bold text-white mb-1">Área Admin</h1>
            <p className="text-slate-400 text-sm">
              Complexo Esportivo · Gestão Interna
            </p>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="px-8 py-8 space-y-5">
            <div className="space-y-2">
              <label className="block text-sm font-medium text-slate-300">
                Senha de acesso
              </label>
              <div className="relative group">
                <Lock className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within:text-emerald-400 transition-colors" />
                <input
                  id="admin-senha"
                  type={mostrarSenha ? "text" : "password"}
                  value={senha}
                  onChange={(e) => {
                    setSenha(e.target.value);
                    if (erro) setErro(false);
                  }}
                  placeholder="••••••••"
                  autoComplete="current-password"
                  className={`w-full bg-slate-800 border rounded-xl pl-10 pr-10 py-3 text-sm text-white placeholder-slate-500 outline-none transition-all
                    ${
                      erro
                        ? "border-red-500/70 focus:border-red-500 focus:ring-2 focus:ring-red-500/20"
                        : "border-slate-700 focus:border-emerald-500 focus:ring-2 focus:ring-emerald-500/20"
                    }`}
                  required
                />
                <button
                  type="button"
                  onClick={() => setMostrarSenha((v) => !v)}
                  className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300 transition-colors"
                >
                  {mostrarSenha ? (
                    <EyeOff className="w-4 h-4" />
                  ) : (
                    <Eye className="w-4 h-4" />
                  )}
                </button>
              </div>
              {erro && (
                <p className="text-red-400 text-xs flex items-center gap-1.5 animate-fade-in">
                  <span className="inline-block w-1 h-1 rounded-full bg-red-400" />
                  Senha incorreta. Tente novamente.
                </p>
              )}
            </div>

            <button
              id="admin-login-btn"
              type="submit"
              disabled={carregando || !senha}
              className="w-full bg-emerald-500 hover:bg-emerald-400 disabled:opacity-50 disabled:cursor-not-allowed text-slate-950 font-semibold rounded-xl py-3 text-sm transition-all duration-200 flex items-center justify-center gap-2 shadow-lg shadow-emerald-500/20"
            >
              {carregando ? (
                <>
                  <span className="inline-block w-4 h-4 border-2 border-slate-950/30 border-t-slate-950 rounded-full animate-spin" />
                  Verificando...
                </>
              ) : (
                "Entrar"
              )}
            </button>
          </form>
        </div>

        <p className="text-center text-slate-600 text-xs mt-6">
          Reservei · Painel Administrativo
        </p>
      </div>

      <style jsx>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          15% { transform: translateX(-6px); }
          30% { transform: translateX(6px); }
          45% { transform: translateX(-4px); }
          60% { transform: translateX(4px); }
          75% { transform: translateX(-2px); }
          90% { transform: translateX(2px); }
        }
        .animate-shake {
          animation: shake 0.45s ease-in-out;
        }
      `}</style>
    </div>
  );
}

/**
 * Sidebar de navegação do painel administrativo.
 * Responsiva: collapsa em menu hambúrguer no mobile.
 */

"use client";

import { useState } from "react";
import {
  LayoutDashboard,
  CalendarDays,
  DollarSign,
  LogOut,
  Menu,
  X,
  Shield,
  ChevronRight,
} from "lucide-react";

export type AdminView = "dashboard" | "agenda" | "financeiro";

interface NavItem {
  id: AdminView;
  label: string;
  icon: React.ElementType;
}

const NAV_ITEMS: NavItem[] = [
  { id: "dashboard", label: "Dashboard", icon: LayoutDashboard },
  { id: "agenda", label: "Agenda de Ocupação", icon: CalendarDays },
  { id: "financeiro", label: "Financeiro", icon: DollarSign },
];

interface Props {
  viewAtual: AdminView;
  onChangeView: (view: AdminView) => void;
  onLogout: () => void;
}

export function AdminSidebar({ viewAtual, onChangeView, onLogout }: Props) {
  const [mobileOpen, setMobileOpen] = useState(false);

  function handleNav(view: AdminView) {
    onChangeView(view);
    setMobileOpen(false);
  }

  const sidebarContent = (
    <div className="flex flex-col h-full">
      {/* Logo */}
      <div className="px-6 py-6 border-b border-slate-700/50">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center flex-shrink-0">
            <Shield className="w-5 h-5 text-emerald-400" />
          </div>
          <div>
            <p className="font-bold text-white text-sm leading-none">Reservei</p>
            <p className="text-slate-500 text-xs mt-0.5">Painel Admin</p>
          </div>
        </div>
      </div>

      {/* Navegação */}
      <nav className="flex-1 px-3 py-4 space-y-1">
        <p className="px-3 text-[10px] font-semibold text-slate-600 uppercase tracking-widest mb-3">
          Navegação
        </p>
        {NAV_ITEMS.map((item) => {
          const Icon = item.icon;
          const ativo = viewAtual === item.id;
          return (
            <button
              key={item.id}
              id={`admin-nav-${item.id}`}
              onClick={() => handleNav(item.id)}
              className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-all duration-200 group
                ${
                  ativo
                    ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"
                    : "text-slate-400 hover:text-white hover:bg-slate-800 border border-transparent"
                }`}
            >
              <Icon
                className={`w-4 h-4 flex-shrink-0 transition-transform duration-200 ${ativo ? "" : "group-hover:scale-110"}`}
              />
              <span className="flex-1 text-left">{item.label}</span>
              {ativo && (
                <ChevronRight className="w-3.5 h-3.5 text-emerald-500" />
              )}
            </button>
          );
        })}
      </nav>

      {/* Logout */}
      <div className="px-3 pb-6 pt-3 border-t border-slate-700/50">
        <button
          id="admin-logout-btn"
          onClick={onLogout}
          className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium text-slate-400 hover:text-red-400 hover:bg-red-500/10 border border-transparent hover:border-red-500/20 transition-all duration-200 group"
        >
          <LogOut className="w-4 h-4 flex-shrink-0 group-hover:-translate-x-0.5 transition-transform duration-200" />
          Sair
        </button>
      </div>
    </div>
  );

  return (
    <>
      {/* ── Desktop Sidebar ─────────────────────────────────────────────────── */}
      <aside className="hidden lg:flex w-60 flex-col flex-shrink-0 bg-slate-900 border-r border-slate-700/50 h-screen sticky top-0">
        {sidebarContent}
      </aside>

      {/* ── Mobile: Topbar com hambúrguer ────────────────────────────────────── */}
      <div className="lg:hidden fixed top-0 left-0 right-0 z-40 bg-slate-900/95 backdrop-blur border-b border-slate-700/50 flex items-center justify-between px-4 py-3">
        <div className="flex items-center gap-2.5">
          <div className="w-7 h-7 rounded-lg bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center">
            <Shield className="w-4 h-4 text-emerald-400" />
          </div>
          <span className="font-bold text-white text-sm">Reservei Admin</span>
        </div>
        <button
          id="admin-menu-hamburguer"
          onClick={() => setMobileOpen((v) => !v)}
          className="w-9 h-9 flex items-center justify-center rounded-xl bg-slate-800 border border-slate-700 text-slate-400 hover:text-white transition-colors"
        >
          {mobileOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
        </button>
      </div>

      {/* ── Mobile: Drawer overlay ────────────────────────────────────────────── */}
      {mobileOpen && (
        <div
          className="lg:hidden fixed inset-0 z-30 bg-black/60 backdrop-blur-sm"
          onClick={() => setMobileOpen(false)}
        />
      )}
      <aside
        className={`lg:hidden fixed top-0 left-0 z-40 h-full w-72 bg-slate-900 border-r border-slate-700/50 transform transition-transform duration-300 ease-in-out pt-[57px]
          ${mobileOpen ? "translate-x-0" : "-translate-x-full"}`}
      >
        {sidebarContent}
      </aside>
    </>
  );
}

/**
 * Página de Visão Geral — KPI Cards do dia atual.
 * Lê dados diretamente do useReservasService (Zustand).
 */

"use client";

import { useMemo } from "react";
import {
  CalendarCheck,
  TrendingUp,
  Clock,
  Activity,
  ArrowUpRight,
} from "lucide-react";
import { useReservasService } from "@/hooks/useReservasService";

function formatarMoeda(valor: number) {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function hoje() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${dd}`;
}

export function AdminDashboardPage() {
  const { reservas } = useReservasService();

  const dataHoje = hoje();

  const kpis = useMemo(() => {
    const reservasHoje = reservas.filter(
      (r) => r.data === dataHoje && r.status !== "cancelada"
    );

    const sinaisPagos = reservasHoje.filter(
      (r) => r.status === "confirmada" || r.status === "pendente"
    );

    const totalSinaisRecebidos = sinaisPagos.reduce(
      (acc, r) => acc + r.valorSinal,
      0
    );

    const totalPendenteNoLocal = reservasHoje
      .filter((r) => r.status === "pendente")
      .reduce((acc, r) => acc + r.valorPendente, 0);

    const totalReservas = reservasHoje.length;

    // Taxa de ocupação das 3 quadras × 15 horários disponíveis
    const totalSlots = 3 * 15;
    const slotsOcupados = reservasHoje.reduce(
      (acc, r) => acc + r.horarios.length,
      0
    );
    const taxaOcupacao =
      totalSlots > 0 ? Math.round((slotsOcupados / totalSlots) * 100) : 0;

    return {
      totalReservas,
      totalSinaisRecebidos,
      totalPendenteNoLocal,
      taxaOcupacao,
    };
  }, [reservas, dataHoje]);

  const cards = [
    {
      id: "kpi-reservas",
      label: "Reservas hoje",
      valor: String(kpis.totalReservas),
      subLabel: "agendamentos ativos",
      icon: CalendarCheck,
      cor: "emerald",
      gradiente: "from-emerald-500/10 to-emerald-500/5",
      borderCor: "border-emerald-500/20",
      iconBg: "bg-emerald-500/10",
      iconCor: "text-emerald-400",
    },
    {
      id: "kpi-sinais",
      label: "Sinais confirmados",
      valor: formatarMoeda(kpis.totalSinaisRecebidos),
      subLabel: "pagos via Pix",
      icon: TrendingUp,
      cor: "sky",
      gradiente: "from-sky-500/10 to-sky-500/5",
      borderCor: "border-sky-500/20",
      iconBg: "bg-sky-500/10",
      iconCor: "text-sky-400",
    },
    {
      id: "kpi-pendente",
      label: "Pendente no local",
      valor: formatarMoeda(kpis.totalPendenteNoLocal),
      subLabel: "a receber presencialmente",
      icon: Clock,
      cor: "amber",
      gradiente: "from-amber-500/10 to-amber-500/5",
      borderCor: "border-amber-500/20",
      iconBg: "bg-amber-500/10",
      iconCor: "text-amber-400",
    },
    {
      id: "kpi-ocupacao",
      label: "Taxa de ocupação",
      valor: `${kpis.taxaOcupacao}%`,
      subLabel: "dos slots disponíveis",
      icon: Activity,
      cor: "violet",
      gradiente: "from-violet-500/10 to-violet-500/5",
      borderCor: "border-violet-500/20",
      iconBg: "bg-violet-500/10",
      iconCor: "text-violet-400",
    },
  ];

  const dataFormatada = new Date().toLocaleDateString("pt-BR", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold text-white">Visão Geral</h1>
        <p className="text-slate-400 text-sm mt-1 capitalize">{dataFormatada}</p>
      </div>

      {/* KPI Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {cards.map((card, i) => {
          const Icon = card.icon;
          return (
            <div
              key={card.id}
              id={card.id}
              className={`relative bg-gradient-to-br ${card.gradiente} border ${card.borderCor} rounded-2xl p-5 overflow-hidden group hover:scale-[1.02] transition-transform duration-200`}
              style={{ animationDelay: `${i * 60}ms` }}
            >
              {/* Decoração de fundo */}
              <div
                className={`absolute -right-4 -top-4 w-24 h-24 rounded-full ${card.iconBg} blur-2xl opacity-60`}
              />

              <div className="relative">
                <div className="flex items-start justify-between mb-4">
                  <div
                    className={`w-10 h-10 rounded-xl ${card.iconBg} border ${card.borderCor} flex items-center justify-center`}
                  >
                    <Icon className={`w-5 h-5 ${card.iconCor}`} />
                  </div>
                  <ArrowUpRight
                    className={`w-4 h-4 ${card.iconCor} opacity-0 group-hover:opacity-100 transition-opacity duration-200`}
                  />
                </div>

                <p className="text-slate-400 text-xs font-medium mb-1">
                  {card.label}
                </p>
                <p className="text-2xl font-bold text-white leading-none mb-1">
                  {card.valor}
                </p>
                <p className="text-slate-500 text-xs">{card.subLabel}</p>
              </div>
            </div>
          );
        })}
      </div>

      {/* Lista de reservas do dia */}
      <div>
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold text-white">
            Reservas de hoje
          </h2>
          <span className="text-xs text-slate-500 bg-slate-800 border border-slate-700 px-2.5 py-1 rounded-full">
            {reservas.filter(
              (r) => r.data === dataHoje && r.status !== "cancelada"
            ).length}{" "}
            ativas
          </span>
        </div>

        <ReservasDoDia reservas={reservas} dataHoje={dataHoje} />
      </div>
    </div>
  );
}

// ── Sub-componente: Lista de reservas ─────────────────────────────────────────

import type { Reserva } from "@/store/useReservasStore";

const STATUS_CONFIG: Record<
  string,
  { label: string; cor: string; bg: string }
> = {
  confirmada: {
    label: "Confirmada",
    cor: "text-emerald-400",
    bg: "bg-emerald-500/10 border-emerald-500/20",
  },
  pendente: {
    label: "Pendente",
    cor: "text-amber-400",
    bg: "bg-amber-500/10 border-amber-500/20",
  },
  em_processamento: {
    label: "Processando",
    cor: "text-sky-400",
    bg: "bg-sky-500/10 border-sky-500/20",
  },
  cancelada: {
    label: "Cancelada",
    cor: "text-slate-500",
    bg: "bg-slate-500/10 border-slate-500/20",
  },
};

function ReservasDoDia({
  reservas,
  dataHoje,
}: {
  reservas: Reserva[];
  dataHoje: string;
}) {
  const reservasHoje = reservas
    .filter((r) => r.data === dataHoje && r.status !== "cancelada")
    .sort((a, b) => a.horaInicio.localeCompare(b.horaInicio));

  if (reservasHoje.length === 0) {
    return (
      <div className="bg-slate-900 border border-slate-700/50 rounded-2xl p-10 text-center">
        <CalendarCheck className="w-10 h-10 text-slate-600 mx-auto mb-3" />
        <p className="text-slate-400 font-medium">Nenhuma reserva para hoje</p>
        <p className="text-slate-600 text-sm mt-1">
          As reservas feitas pelo portal aparecerão aqui em tempo real.
        </p>
      </div>
    );
  }

  return (
    <div className="bg-slate-900 border border-slate-700/50 rounded-2xl overflow-hidden">
      {/* Header da tabela */}
      <div className="hidden sm:grid grid-cols-[1fr_auto_auto_auto] gap-4 px-5 py-3 border-b border-slate-700/50 text-xs font-medium text-slate-500 uppercase tracking-wider">
        <span>Cliente</span>
        <span className="text-center">Quadra</span>
        <span className="text-center">Horário</span>
        <span className="text-right">Status</span>
      </div>

      {/* Linhas */}
      <div className="divide-y divide-slate-700/30">
        {reservasHoje.map((r) => {
          const cfg = STATUS_CONFIG[r.status] ?? STATUS_CONFIG.pendente;
          const quadraNum = r.quadraId.replace("q", "");
          return (
            <div
              key={r.id}
              className="px-5 py-4 flex flex-col sm:grid sm:grid-cols-[1fr_auto_auto_auto] gap-3 sm:gap-4 sm:items-center hover:bg-slate-800/40 transition-colors duration-150"
            >
              {/* Nome + esporte */}
              <div>
                <p className="font-medium text-white text-sm">
                  {r.nomeCliente || "—"}
                </p>
                <p className="text-slate-500 text-xs mt-0.5">
                  {r.esporte ?? "Sem esporte"} ·{" "}
                  {formatarMoeda(r.valorSinal)} sinal
                </p>
              </div>

              {/* Quadra */}
              <div className="text-center">
                <span className="text-xs font-medium text-slate-300 bg-slate-800 border border-slate-700 px-2.5 py-1 rounded-lg">
                  Quadra {quadraNum}
                </span>
              </div>

              {/* Horário */}
              <div className="text-center">
                <span className="text-xs font-mono text-slate-300">
                  {r.horaInicio} – {r.horaFim}
                </span>
              </div>

              {/* Status */}
              <div className="sm:text-right">
                <span
                  className={`text-xs font-medium px-2.5 py-1 rounded-full border ${cfg.bg} ${cfg.cor}`}
                >
                  {cfg.label}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/**
 * AdminShell — Orquestrador da área administrativa.
 * Gerencia autenticação, roteamento interno e layout com Sidebar.
 */

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useAdminAuth } from "@/hooks/useAdminAuth";
import { AdminLogin } from "./AdminLogin";
import { AdminSidebar, type AdminView } from "./AdminSidebar";
import { AdminDashboardPage } from "./AdminDashboardPage";

// Placeholder pages para futuras specs
function PlaceholderPage({ titulo }: { titulo: string }) {
  return (
    <div className="flex flex-col items-center justify-center h-[60vh] text-center animate-fade-in">
      <div className="w-16 h-16 rounded-2xl bg-slate-800 border border-slate-700 flex items-center justify-center mb-5">
        <span className="text-3xl">🚧</span>
      </div>
      <h2 className="text-xl font-bold text-white mb-2">{titulo}</h2>
      <p className="text-slate-400 text-sm max-w-xs">
        Esta seção está planejada e será implementada na próxima especificação.
      </p>
    </div>
  );
}

interface Props {
  initialView?: AdminView;
}

export function AdminShell({ initialView = "dashboard" }: Props) {
  const { autenticado, login, logout } = useAdminAuth();
  const [view, setView] = useState<AdminView>(initialView);
  const router = useRouter();

  // Redireciona para /admin/dashboard após login bem-sucedido
  useEffect(() => {
    if (autenticado && typeof window !== "undefined") {
      const pathAtual = window.location.pathname;
      if (pathAtual === "/admin") {
        router.replace("/admin/dashboard");
      }
    }
  }, [autenticado, router]);

  // ── Carregando (hidratação do LocalStorage) ──────────────────────────────
  if (autenticado === null) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <span className="inline-block w-6 h-6 border-2 border-slate-700 border-t-emerald-400 rounded-full animate-spin" />
      </div>
    );
  }

  // ── Não autenticado → Tela de login ──────────────────────────────────────
  if (!autenticado) {
    return <AdminLogin onLogin={login} />;
  }

  // ── Autenticado → Layout principal ───────────────────────────────────────
  return (
    <div className="flex min-h-screen bg-slate-950">
      <AdminSidebar
        viewAtual={view}
        onChangeView={setView}
        onLogout={logout}
      />

      {/* Conteúdo principal */}
      <main className="flex-1 min-w-0 lg:pt-0 pt-[57px]">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {view === "dashboard" && <AdminDashboardPage />}
          {view === "agenda" && (
            <PlaceholderPage titulo="Agenda de Ocupação" />
          )}
          {view === "financeiro" && (
            <PlaceholderPage titulo="Financeiro" />
          )}
        </div>
      </main>
    </div>
  );
}

