/**
 * ModalDetalhesReserva — exibe todas as informações de uma reserva.
 * Acionado pelo clique em qualquer item da tabela (Dashboard) ou
 * bloco da timeline (Agenda).
 */

"use client";

import { useEffect, useCallback } from "react";
import {
  X,
  User,
  Phone,
  CreditCard,
  CalendarDays,
  Clock,
  Layers,
  Dumbbell,
  MessageSquare,
  Banknote,
  CheckCircle2,
  AlertCircle,
  Loader2,
  XCircle,
  DollarSign,
} from "lucide-react";
import type { Reserva } from "@/store/useReservasStore";
import { formatarMoeda, formatarDataExibicao } from "@/lib/constants";
import { PREPARACAO_POR_ESPORTE } from "@/lib/quadras";

// ─── Config de status ─────────────────────────────────────────────────────────

const STATUS_CONFIG = {
  confirmada: {
    label: "Confirmada",
    icon: CheckCircle2,
    bg: "bg-emerald-500/10 border-emerald-500/30",
    text: "text-emerald-400",
    iconCor: "text-emerald-400",
  },
  pendente: {
    label: "Pendente (pagar no local)",
    icon: AlertCircle,
    bg: "bg-amber-500/10 border-amber-500/30",
    text: "text-amber-400",
    iconCor: "text-amber-400",
  },
  em_processamento: {
    label: "Em Processamento",
    icon: Loader2,
    bg: "bg-sky-500/10 border-sky-500/30",
    text: "text-sky-400",
    iconCor: "text-sky-400",
  },
  cancelada: {
    label: "Cancelada",
    icon: XCircle,
    bg: "bg-slate-600/20 border-slate-600/30",
    text: "text-slate-500",
    iconCor: "text-slate-500",
  },
};

// ─── Sub-componente: Linha de detalhe ─────────────────────────────────────────

function DetalheRow({
  icon: Icon,
  label,
  value,
  valueClass = "text-white",
}: {
  icon: React.ElementType;
  label: string;
  value: React.ReactNode;
  valueClass?: string;
}) {
  return (
    <div className="flex items-start gap-3 py-3 border-b border-slate-700/40 last:border-0">
      <div className="w-7 h-7 rounded-lg bg-slate-800 flex items-center justify-center flex-shrink-0 mt-0.5">
        <Icon className="w-3.5 h-3.5 text-slate-400" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-[11px] text-slate-500 font-medium uppercase tracking-wide mb-0.5">
          {label}
        </p>
        <p className={`text-sm font-medium break-words ${valueClass}`}>{value}</p>
      </div>
    </div>
  );
}

// ─── Componente principal ─────────────────────────────────────────────────────

interface Props {
  reserva: Reserva | null;
  onFechar: () => void;
}

export function ModalDetalhesReserva({ reserva, onFechar }: Props) {
  // Fechar com Escape
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") onFechar();
    },
    [onFechar]
  );

  useEffect(() => {
    if (!reserva) return;
    document.addEventListener("keydown", handleKeyDown);
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      document.body.style.overflow = "";
    };
  }, [reserva, handleKeyDown]);

  if (!reserva) return null;

  const statusCfg =
    STATUS_CONFIG[reserva.status] ?? STATUS_CONFIG.pendente;
  const StatusIcon = statusCfg.icon;

  const quadraNum = reserva.quadraId.replace("q", "");
  const tipoPagamento = reserva.valorPendente === 0 ? "integral" : "sinal";
  const dataFormatada = formatarDataExibicao(reserva.data, {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
  const criadaEm = new Date(reserva.criadaEm).toLocaleString("pt-BR", {
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });

  return (
    <>
      {/* Overlay */}
      <div
        className="fixed inset-0 z-50 bg-black/70 backdrop-blur-sm animate-fade-in"
        onClick={onFechar}
      />

      {/* Drawer lateral */}
      <div className="fixed inset-y-0 right-0 z-50 w-full max-w-md flex flex-col bg-slate-900 border-l border-slate-700/60 shadow-2xl animate-slide-in-right overflow-y-auto">

        {/* Header */}
        <div className="flex items-start justify-between px-6 pt-6 pb-5 border-b border-slate-700/50 sticky top-0 bg-slate-900 z-10">
          <div>
            <p className="text-xs text-slate-500 font-mono mb-1">
              #{reserva.id.slice(-8).toUpperCase()}
            </p>
            <h2 className="text-lg font-bold text-white leading-tight">
              Detalhes da Reserva
            </h2>
          </div>
          <button
            id="modal-detalhes-fechar"
            onClick={onFechar}
            className="w-9 h-9 flex items-center justify-center rounded-xl bg-slate-800 border border-slate-700 text-slate-400 hover:text-white hover:border-slate-600 transition-all flex-shrink-0 ml-4"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="flex-1 px-6 py-5 space-y-6">

          {/* Badge de status */}
          <div
            className={`flex items-center gap-2.5 px-4 py-3 rounded-xl border ${statusCfg.bg}`}
          >
            <StatusIcon className={`w-5 h-5 flex-shrink-0 ${statusCfg.iconCor}`} />
            <div>
              <p className={`text-sm font-semibold ${statusCfg.text}`}>
                {statusCfg.label}
              </p>
              <p className="text-[11px] text-slate-500 mt-0.5">
                Reserva criada em {criadaEm}
              </p>
            </div>
          </div>

          {/* Seção: Cliente */}
          <section>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-widest mb-3">
              Cliente
            </p>
            <div className="bg-slate-800/50 border border-slate-700/50 rounded-xl px-4">
              <DetalheRow
                icon={User}
                label="Nome"
                value={reserva.nomeCliente || "—"}
              />
              <DetalheRow
                icon={Phone}
                label="WhatsApp"
                value={reserva.whatsappCliente || "—"}
              />
              <DetalheRow
                icon={CreditCard}
                label="CPF"
                value={reserva.cpfCliente || "—"}
              />
            </div>
          </section>

          {/* Seção: Agendamento */}
          <section>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-widest mb-3">
              Agendamento
            </p>
            <div className="bg-slate-800/50 border border-slate-700/50 rounded-xl px-4">
              <DetalheRow
                icon={CalendarDays}
                label="Data"
                value={<span className="capitalize">{dataFormatada}</span>}
              />
              <DetalheRow
                icon={Clock}
                label="Horário"
                value={`${reserva.horaInicio} – ${reserva.horaFim} (${reserva.horarios.length}h)`}
                valueClass="text-white font-mono"
              />
              <DetalheRow
                icon={Layers}
                label="Quadra"
                value={`Quadra ${quadraNum} — poliesportiva coberta`}
              />
              {reserva.esporte && (
                <DetalheRow
                  icon={Dumbbell}
                  label="Esporte"
                  value={
                    <span>
                      {reserva.esporte}
                      <span className="block text-[11px] text-slate-500 font-normal mt-0.5">
                        {PREPARACAO_POR_ESPORTE[reserva.esporte]}
                      </span>
                    </span>
                  }
                />
              )}
              {reserva.observacoes && (
                <DetalheRow
                  icon={MessageSquare}
                  label="Observações"
                  value={reserva.observacoes}
                  valueClass="text-slate-300"
                />
              )}
            </div>
          </section>

          {/* Seção: Financeiro */}
          <section>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-widest mb-3">
              Financeiro
            </p>
            <div className="bg-slate-800/50 border border-slate-700/50 rounded-xl px-4">
              <DetalheRow
                icon={DollarSign}
                label="Valor total"
                value={formatarMoeda(reserva.valorTotal)}
                valueClass="text-white"
              />
              <DetalheRow
                icon={Banknote}
                label={tipoPagamento === "integral" ? "Pago (integral)" : "Sinal pago (40%)"}
                value={formatarMoeda(reserva.valorSinal)}
                valueClass="text-emerald-400"
              />
              {tipoPagamento === "sinal" && (
                <DetalheRow
                  icon={AlertCircle}
                  label="Pendente no local (60%)"
                  value={formatarMoeda(reserva.valorPendente)}
                  valueClass="text-amber-400"
                />
              )}
            </div>

            {/* Resumo visual */}
            <div className="mt-3 bg-slate-800/50 border border-slate-700/50 rounded-xl p-4">
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs text-slate-400">
                  {tipoPagamento === "integral" ? "Pago integralmente" : "Progresso do pagamento"}
                </span>
                <span className="text-xs font-mono text-slate-300">
                  {tipoPagamento === "integral"
                    ? "100%"
                    : `${Math.round((reserva.valorSinal / reserva.valorTotal) * 100)}%`}
                </span>
              </div>
              <div className="h-2 bg-slate-700 rounded-full overflow-hidden">
                <div
                  className={`h-full rounded-full transition-all duration-500 ${
                    tipoPagamento === "integral"
                      ? "bg-emerald-500"
                      : "bg-amber-500"
                  }`}
                  style={{
                    width:
                      tipoPagamento === "integral"
                        ? "100%"
                        : `${Math.round((reserva.valorSinal / reserva.valorTotal) * 100)}%`,
                  }}
                />
              </div>
            </div>
          </section>

          {/* Seção: WhatsApp */}
          <section>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-widest mb-3">
              Notificação
            </p>
            <div className="bg-slate-800/50 border border-slate-700/50 rounded-xl px-4">
              <DetalheRow
                icon={Phone}
                label="Status WhatsApp"
                value={
                  reserva.statusWhatsApp === "enviado"
                    ? "✅ Confirmação enviada"
                    : reserva.statusWhatsApp === "falhou"
                    ? "❌ Falha no envio"
                    : "⏳ Não enviado"
                }
                valueClass={
                  reserva.statusWhatsApp === "enviado"
                    ? "text-emerald-400"
                    : reserva.statusWhatsApp === "falhou"
                    ? "text-red-400"
                    : "text-slate-400"
                }
              />
            </div>
          </section>
        </div>
      </div>

      <style jsx>{`
        @keyframes slide-in-right {
          from { transform: translateX(100%); opacity: 0; }
          to   { transform: translateX(0);    opacity: 1; }
        }
        .animate-slide-in-right {
          animation: slide-in-right 0.25s cubic-bezier(0.16, 1, 0.3, 1);
        }
      `}</style>
    </>
  );
}

ReplacementChunks.ReplacementContent:
function ReservasDoDia({
  reservas,
  dataHoje,
}: {
  reservas: Reserva[];
  dataHoje: string;
}) {
  const [reservaSelecionada, setReservaSelecionada] = useState<Reserva | null>(null);

  const reservasHoje = reservas
    .filter((r) => r.data === dataHoje && r.status !== "cancelada")
    .sort((a, b) => a.horaInicio.localeCompare(b.horaInicio));

  if (reservasHoje.length === 0) {
    return (
      <div className="bg-slate-900 border border-slate-700/50 rounded-2xl p-10 text-center">
        <CalendarCheck className="w-10 h-10 text-slate-600 mx-auto mb-3" />
        <p className="text-slate-400 font-medium">Nenhuma reserva para hoje</p>
        <p className="text-slate-600 text-sm mt-1">
          As reservas feitas pelo portal aparecerão aqui em tempo real.
        </p>
      </div>
    );
  }

  return (
    <>
      <div className="bg-slate-900 border border-slate-700/50 rounded-2xl overflow-hidden">
        {/* Header da tabela */}
        <div className="hidden sm:grid grid-cols-[1fr_auto_auto_auto] gap-4 px-5 py-3 border-b border-slate-700/50 text-xs font-medium text-slate-500 uppercase tracking-wider">
          <span>Cliente</span>
          <span className="text-center">Quadra</span>
          <span className="text-center">Horário</span>
          <span className="text-right">Status</span>
        </div>

        {/* Linhas clicáveis */}
        <div className="divide-y divide-slate-700/30">
          {reservasHoje.map((r) => {
            const cfg = STATUS_CONFIG[r.status] ?? STATUS_CONFIG.pendente;
            const quadraNum = r.quadraId.replace("q", "");
            return (
              <button
                key={r.id}
                onClick={() => setReservaSelecionada(r)}
                className="w-full text-left px-5 py-4 flex flex-col sm:grid sm:grid-cols-[1fr_auto_auto_auto] gap-3 sm:gap-4 sm:items-center hover:bg-slate-800/60 active:bg-slate-800 transition-colors duration-150 cursor-pointer group"
              >
                {/* Nome + esporte */}
                <div>
                  <p className="font-medium text-white text-sm group-hover:text-emerald-300 transition-colors">
                    {r.nomeCliente || "—"}
                  </p>
                  <p className="text-slate-500 text-xs mt-0.5">
                    {r.esporte ?? "Sem esporte"} ·{" "}
                    {r.valorPendente === 0
                      ? `${formatarMoeda(r.valorSinal)} integral`
                      : `${formatarMoeda(r.valorSinal)} sinal`}
                  </p>
                </div>

                {/* Quadra */}
                <div className="text-center">
                  <span className="text-xs font-medium text-slate-300 bg-slate-800 border border-slate-700 px-2.5 py-1 rounded-lg">
                    Quadra {quadraNum}
                  </span>
                </div>

                {/* Horário */}
                <div className="text-center">
                  <span className="text-xs font-mono text-slate-300">
                    {r.horaInicio} – {r.horaFim}
                  </span>
                </div>

                {/* Status */}
                <div className="sm:text-right">
                  <span
                    className={`text-xs font-medium px-2.5 py-1 rounded-full border ${cfg.bg} ${cfg.cor}`}
                  >
                    {cfg.label}
                  </span>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <ModalDetalhesReserva
        reserva={reservaSelecionada}
        onFechar={() => setReservaSelecionada(null)}
      />
    </>
  );
}

