    <BotoesWhatsApp reserva={reserva} tipoPagamento={tipoPagamento} />
  ) : (
    <p className="text-slate-600 text-xs text-center py-3">
      Número de WhatsApp não informado pelo cliente.
    </p>
  )}
</section>

